<template><section class="space-y-6"><div class="rounded-2xl border border-amber-500/20 bg-gradient-to-r from-amber-500/10 to-transparent p-6"><p class="text-xs font-semibold tracking-[0.18em] text-amber-700 dark:text-amber-300">ATELIÊ</p><h1 class="mt-1 text-3xl font-bold">Peças</h1><p class="mt-1 text-sm text-muted-foreground">Galeria e rastreabilidade de todas as peças sob custódia.</p></div><div v-if="loading" class="py-12 text-center text-sm text-muted-foreground">Carregando peças…</div><div v-else class="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><RouterLink v-for="piece in pieces" :key="piece.id" :to="{ name: 'ourive-ordem', params: { id: piece.orderId } }" class="rounded-xl border bg-card p-4 transition hover:border-amber-500/60 hover:shadow-sm"><div class="mb-3 flex aspect-[4/3] items-center justify-center overflow-hidden rounded-lg bg-muted"><img v-if="piece.foto" :src="piece.foto" :alt="piece.descricao" class="h-full w-full object-cover" /><Gem v-else class="h-10 w-10 text-muted-foreground" /></div><p class="font-semibold">{{ piece.descricao }}</p><p class="mt-1 text-xs text-muted-foreground">{{ piece.codigoRastreio }} · {{ piece.cliente }}</p><p class="mt-2 text-sm text-muted-foreground">{{ piece.metal || 'Metal não informado' }}</p></RouterLink><div v-if="!pieces.length" class="col-span-full py-12 text-center text-sm text-muted-foreground">Nenhuma peça cadastrada.</div></div></section></template>
<script setup lang="ts">import { onMounted, ref } from 'vue'; import { useToast } from 'vue-toastification'; import { Gem } from 'lucide-vue-next'; import { OuriveRepository } from '@/repositories/ourive-repository'; const toast = useToast(); const loading = ref(true); const pieces = ref<any[]>([]); async function load() { loading.value = true; try { const orders = (await OuriveRepository.ordens()).items; const details = await Promise.all(orders.map((item: any) => OuriveRepository.ordem(item.id))); pieces.value = details.flatMap((order: any) => order.pecas.map((piece: any) => ({ ...piece, orderId: order.id, cliente: order.ordemServico?.Cliente?.nome || 'Cliente', foto: piece.fotos?.[0]?.url }))) } catch { toast.error('Não foi possível carregar as peças.') } finally { loading.value = false } } onMounted(load)</script>
